def conservative_fill(row):
    nonzero = [(c,v) for c,v in enumerate(row) if v != 0]
    if not nonzero:
        return row[:]

    # If only 1 or 2 non-zero cells, likely a dot row - skip
    if len(nonzero) <= 2:
        return row[:]

    result = row[:]

    # Group contiguous blocks
    blocks = []
    curr = [nonzero[0]]
    for i in range(1, len(nonzero)):
        c, v = nonzero[i]
        prev_c = nonzero[i-1][0]
        if abs(c - prev_c) <= 2:
            curr.append((c,v))
        else:
            blocks.append(curr)
            curr = [(c,v)]
    blocks.append(curr)

    for block in blocks:
        min_c = min(c for c,_ in block)
        max_c = max(c for c,_ in block)

        # Fill internal gaps
        for c in range(min_c, max_c + 1):
            if result[c] == 0:
                result[c] = block[0][1]

        center = (min_c + max_c) / 2

        if center < 5:
            for c in range(max_c + 1, 9):
                if result[c] == 0:
                    result[c] = block[0][1]
        elif center > 10:
            for c in range(3, min(min_c, 9)):
                if result[c] == 0:
                    result[c] = block[0][1]

    return result

